#pragma once
static void checkHoverDelete(App& app,const std::string& dir){
    auto& s=app.s;int cases=0;
    auto require=[](bool ok,const std::string& why){if(!ok)throw std::runtime_error("hover Delete: "+why);};
    auto reset=[&](const Document& doc){s.cancel();s.doc=doc;s.history.clear();s.selected.clear();s.input.bindDocument(s.doc.id());s.activateCommand("chooseSelectionTool_Marquee");app.rapidSprout.clear();app.selectedElectronMarker={};app.down=false;app.pointerOverCanvas=true;s.refresh();};
    auto hover=[&](Vec2 world){auto view=s.view();view.center=world;view.scale=4;view.dpiScale=1;s.setView(view);auto p=view.toDevice(world);SendMessageW(app.canvas,WM_MOUSEMOVE,0,MAKELPARAM(int(std::lround(p.x)),int(std::lround(p.y))));s.input.refreshHotspot(&s);};
    auto del=[&](){SendMessageW(app.canvas,WM_KEYDOWN,VK_DELETE,0);SendMessageW(app.canvas,WM_KEYUP,VK_DELETE,0);};
    auto undoRedo=[&](const Document& before){auto after=s.doc.digest();require(app.shortcut('Z',kModControl,false)&&s.doc.digest()==before.digest(),"Ctrl+Z restores exact document");require(app.shortcut('Y',kModControl,false)&&s.doc.digest()==after,"Ctrl+Y restores exact deletion");};
    Document chain;ObjectId a,b,c,ab,bc;chain.addAtom(Vec2(-32,0),6,&a);chain.addAtom(Vec2(),6,&b);chain.addAtom(Vec2(32,0),8,&c);chain.addBond(a,b,&ab);chain.addBond(b,c,&bc);
    for(auto target:{a,b,c}){reset(chain);hover(chain.atoms().alive(target)->position);require(s.input.hotspot().kind==interaction::HotspotKind::Atom&&s.input.hotspot().object.id==target,"real atom capture");del();require(!s.doc.atoms().alive(target)&&s.doc.stats().aliveAtoms==2,"delete atom, not its label or entire structure");for(auto id:{ab,bc}){auto bond=chain.bonds().alive(id);require(bool(s.doc.bonds().alive(id))==(bond->beginAtom!=target&&bond->endAtom!=target),"only incident bonds cascade");}undoRedo(chain);++cases;}
    reset(chain);hover(Vec2(-16,0));require(s.input.hotspot().kind==interaction::HotspotKind::Bond,"real bond capture");del();require(!s.doc.bonds().alive(ab)&&s.doc.bonds().alive(bc)&&s.doc.stats().aliveAtoms==3,"bond deletion preserves endpoint atoms");undoRedo(chain);++cases;
    {Document ring;std::vector<ObjectId> atoms;ObjectId first;for(int i=0;i<6;++i){ObjectId id;ring.addAtom(direction(i*60)*32,6,&id);atoms.push_back(id);}for(int i=0;i<6;++i){ObjectId id;ring.addBond(atoms[i],atoms[(i+1)%6],&id);if(!i)first=id;}reset(ring);hover((ring.atoms().alive(atoms[0])->position+ring.atoms().alive(atoms[1])->position)*.5);del();require(s.doc.stats().aliveAtoms==6&&s.doc.stats().aliveBonds==5&&!s.doc.bonds().alive(first),"ring bond opens ring without deleting atoms");undoRedo(ring);++cases;}
    for(auto kind:{ObjectKind::Atom,ObjectKind::Bond}){reset(chain);ObjectRef selected(kind,kind==ObjectKind::Atom?a:ab);s.selected={selected};hover(chain.atoms().alive(c)->position);del();require(s.doc.atoms().alive(c)&&(kind==ObjectKind::Atom?!s.doc.atoms().alive(a):!s.doc.bonds().alive(ab)),"explicit selection has priority over hover");undoRedo(chain);++cases;}
    reset(chain);hover(Vec2(180,140));del();require(s.doc.digest()==chain.digest()&&s.history.cursor()==0,"empty canvas has no deletion or undo step");hover(Vec2());app.pointerOverCanvas=false;del();require(s.doc.digest()==chain.digest()&&s.history.cursor()==0,"canvas leave cannot delete stale capture");++cases;
    reset(chain);hover(Vec2());app.down=true;require(app.shortcut(VK_DELETE,0,false)&&s.doc.digest()==chain.digest(),"active gesture is not interrupted by hover deletion");app.down=false;require(!app.shortcut(VK_DELETE,0,true)&&s.doc.digest()==chain.digest(),"editor shortcut does not delete geometry");++cases;
    reset(chain);hover(chain.atoms().alive(c)->position);app.openText(kInvalidObjectId,c);require(app.textEditor.active,"open native atom label editor");app.textEditor.select(0,-1);SendMessageW(app.edit,EM_REPLACESEL,TRUE,LPARAM(L"NH2"));app.textEditor.select(1,2);del();require(app.textEditor.active&&s.doc.digest()==chain.digest(),"Delete in text editor leaves geometry intact");auto length=GetWindowTextLengthW(app.edit);std::wstring text(size_t(length)+1,L'\0');GetWindowTextW(app.edit,&text[0],length+1);require(text.substr(0,size_t(length))==L"N2","native editor receives Delete");require(app.finishText(false),"cancel test text editor");++cases;
    reset(chain);require(s.submit(mechanism::setLonePairCommand({c}),"test lone pair").ok(),"create lone pair");const auto withPair=s.doc;const auto pairBox=arrows::mechanismVisualBoxes(s.doc).at(c).lonePairs.at(0);hover((pairBox.min+pairBox.max)*.5);require(app.electronMarkerAt(s.view().toDocument(app.pointerPixel),3,false,true).atom==c,"real printed lone-pair capture");del();require(s.doc.atoms().alive(c)&&mechanism::lonePairCount(s.doc,c)==0,"hovered electron marker deletes marker, not its atom");undoRedo(withPair);++cases;
    reset(chain);hover(Vec2());del();const auto digest=s.doc.digest();require(s.save(dir+"/hover-delete-result.r62doc",false).ok(),"save deletion");Session reopened;require(reopened.open(dir+"/hover-delete-result.r62doc").ok()&&reopened.doc.digest()==digest,"native deletion round trip");++cases;
    reset(Document());app.pointerOverCanvas=false;
    std::ofstream(dir+"/hover-delete-checks.json")<<"{\"cases\":"<<cases<<",\"native_Delete_key\":true,\"atoms_and_bonds\":true,\"incident_bonds_only\":true,\"ring_opening\":true,\"selection_priority\":true,\"stale_capture_safe\":true,\"text_editing\":true,\"electron_marker_priority\":true,\"undo_redo\":true,\"native_round_trip\":true}";
}
